<script setup lang="ts">definePageMeta({layout:'admin'});const api=useApi();const resources=['pages','products','collections','events','contacts'];const rows=await Promise.all(resources.map(async resource=>{try{return {resource,items:await api(`/api/${resource}`)}}catch{return {resource,items:[]}}}));const labels={pages:'Páginas',products:'Produtos',collections:'Coleções',events:'Feiras',contacts:'Contactos'};const icons={pages:'lucide:file-text',products:'lucide:package',collections:'lucide:book-open',events:'lucide:calendar-days',contacts:'lucide:messages-square'};const stats=rows.map(x=>({label:labels[x.resource],value:x.items.length,icon:icons[x.resource],tone:x.resource==='contacts'?'red':'green'}));const newContacts=rows.find(x=>x.resource==='contacts')?.items.filter(x=>x.status==='new')||[]</script>
<template><div class="page-stack"><section class="page-heading"><div><p class="eyebrow">Visão geral</p><h1>Painel de controlo</h1><p class="page-heading__description">O centro de controlo do website AM Moreira.</p></div><div class="page-heading__actions"><NuxtLink class="btn btn--secondary" to="/" target="_blank"><Icon name="lucide:external-link"/> Ver website</NuxtLink><NuxtLink class="btn btn--primary" to="/admin/paginas?new=1"><Icon name="lucide:plus"/> Nova página</NuxtLink></div></section><section class="stats-grid"><CmsStatCard v-for="stat in stats" :key="stat.label" v-bind="stat"/></section><section class="dashboard-grid"><article class="panel quick-actions"><div class="panel__header"><div><h2>Ações rápidas</h2><p>Gerir conteúdo essencial</p></div></div><NuxtLink class="quick-action" to="/admin/produtos?new=1"><span><Icon name="lucide:package-plus"/></span><div><strong>Adicionar produto</strong><small>Catálogo informativo</small></div></NuxtLink><NuxtLink class="quick-action" to="/admin/eventos?new=1"><span><Icon name="lucide:calendar-plus"/></span><div><strong>Adicionar feira</strong><small>Agenda da marca</small></div></NuxtLink><NuxtLink class="quick-action" to="/admin/media"><span><Icon name="lucide:image-plus"/></span><div><strong>Carregar imagens</strong><small>Biblioteca de media</small></div></NuxtLink></article><article class="panel"><div class="panel__header"><div><h2>Novos contactos</h2><p>Pedidos por analisar</p></div><NuxtLink class="text-button" to="/admin/contactos">Ver todos</NuxtLink></div><div v-if="newContacts.length" style="padding:0 24px 24px"><p v-for="item in newContacts.slice(0,5)" :key="item.id"><strong>{{item.name}}</strong> · {{item.subject}}</p></div><div v-else class="empty-state"><h3>Tudo tratado</h3><p>Não existem novos pedidos.</p></div></article></section></div></template>
